-- STAGE 2 DRAFT: offers_cost_breakdown. NOT APPLIED anywhere. Kept outside supabase/migrations so no
-- tool can push it by accident. See docs/marketplace-backend-plan.md §7 "Stage 2".
--
-- Traveller offers get a transparent INR cost breakdown. Every amount is whole rupees except the
-- product's foreign price. Two totals are generated by the database, so no client can send its own:
--   agreed_total_inr    = what the traveller commits to (fee + delivery + other costs, plus the product
--                         price only when the traveller fixes it in INR)
--   estimated_total_inr = everything, including the product at the traveller's rate and any customs
--                         estimate. Customs can never be confirmed before arrival.
-- Users can only INSERT offers (no edit, withdraw or accept yet); status changes come in stage 4.

-- 1. Same meaning as before (the traveller's own fee), clearer name. Its insert grant follows the column.
alter table public.offers rename column reward_inr to service_fee_inr;

-- 2. One statement: new columns, generated totals and all checks, so the table is never half-shaped.
alter table public.offers
  add column product_price_amount numeric(12, 2)
    check (product_price_amount > 0 and product_price_amount < 100000000),
  add column product_currency text
    check (product_currency in ('INR', 'USD', 'EUR', 'GBP', 'AED', 'JPY', 'SGD')),
  add column fx_rate_to_inr numeric(12, 6)
    check (fx_rate_to_inr > 0 and fx_rate_to_inr <= 10000),
  add column product_price_fixed boolean not null default false,
  add column customs_estimate_inr integer
    check (customs_estimate_inr between 0 and 10000000),
  add column customs_note text check (char_length(customs_note) <= 300),
  add column delivery_inr integer not null default 0 check (delivery_inr between 0 and 1000000),
  add column other_costs_inr integer not null default 0 check (other_costs_inr between 0 and 1000000),
  add column other_costs_note text check (char_length(other_costs_note) <= 300),
  add column arrival_date date,
  add column handoff_method text
    check (handoff_method in ('meet_in_person', 'courier_in_india', 'pickup_point')),
  add column declares_lawful_import boolean not null default false,
  -- Rounded half away from zero to whole rupees, e.g. 249.99 USD at 83.456789 = 20,863.
  add column product_price_inr bigint
    generated always as (round(product_price_amount * fx_rate_to_inr)::bigint) stored,
  add column agreed_total_inr bigint generated always as (
    service_fee_inr + delivery_inr + other_costs_inr
    + case when product_price_fixed then coalesce(round(product_price_amount * fx_rate_to_inr)::bigint, 0) else 0 end
  ) stored,
  add column estimated_total_inr bigint generated always as (
    coalesce(round(product_price_amount * fx_rate_to_inr)::bigint, 0)
    + service_fee_inr + delivery_inr + other_costs_inr + coalesce(customs_estimate_inr, 0)
  ) stored,
  add constraint offers_product_price_inr_range check (product_price_inr between 1 and 10000000),
  add constraint offers_inr_rate_is_one check (product_currency is distinct from 'INR' or fx_rate_to_inr = 1),
  add constraint offers_other_costs_explained
    check (other_costs_inr = 0 or char_length(btrim(coalesce(other_costs_note, ''))) >= 3),
  -- New and edited offers must be complete. NOT VALID: older rows (none on dev) aren't re-checked.
  add constraint offers_complete check (
    product_price_amount is not null and product_currency is not null and fx_rate_to_inr is not null
    and arrival_date is not null and handoff_method is not null and declares_lawful_import
  ) not valid,
  drop constraint offers_status_check,
  add constraint offers_status_check
    check (status in ('pending', 'accepted', 'rejected', 'withdrawn', 'closed'));

alter table public.offers rename constraint offers_reward_inr_check to offers_service_fee_inr_check;

-- 3. Backstop for stage 4's accept_offer(): a request can never have two accepted offers.
create unique index offers_one_accepted_per_request on public.offers (request_id) where status = 'accepted';

-- 4. Tighten who may offer: also refuse expired requests and arrival dates in the past (UTC date).
alter policy "Phone-verified travellers can offer on others' open requests" on public.offers
  with check (
    traveller_id = (select auth.uid())
    and (select public.is_phone_verified())
    and arrival_date >= current_date
    and exists (
      select 1
      from public.requests r
      where r.id = request_id
        and r.shopper_id <> (select auth.uid())
        and r.status = 'open'
        and (r.expires_at is null or r.expires_at > now())
    )
  );

-- 5. Last, so permissions only widen once everything above exists: travellers may fill in the breakdown.
-- Still never granted: id, traveller_id, status, created_at and the three generated amounts.
grant insert (
  product_price_amount, product_currency, fx_rate_to_inr, product_price_fixed,
  customs_estimate_inr, customs_note, delivery_inr, other_costs_inr, other_costs_note,
  arrival_date, handoff_method, declares_lawful_import
) on public.offers to authenticated;

comment on column public.offers.product_price_fixed is
  'True: the traveller commits to product_price_inr in rupees. False: it is an estimate that may change with the store price or exchange rate.';
comment on column public.offers.fx_rate_to_inr is
  'The traveller''s own assumed rate (1 for INR). Orbitly does not supply or guarantee exchange rates.';
comment on column public.offers.customs_estimate_inr is
  'Always an estimate: duty is decided by customs at arrival. NULL means not estimated and not included in any total.';
comment on column public.offers.agreed_total_inr is
  'Generated: amounts the traveller commits to. Fee, delivery and other costs, plus the product price only if fixed.';
comment on column public.offers.estimated_total_inr is
  'Generated: product (at the stated rate), fee, delivery, other costs and the customs estimate if given.';
